          n: weeks.length + 1, start: date, end: addDays(date, 6),
          opening: balance, confirmedIncome: 0, estimatedIncome: 0,
          obligations: 0, bills: 0, commitments: 0, reservePlanning: 0, variable: 0, reserved: 0, extra: 0, noncash: 0,
