  function calendarPeriodRole(asOfHalf, half) {
    if (!asOfHalf) return 'future';
    if (half < asOfHalf) return 'lookback';
    if (half === asOfHalf) return 'active';
    return 'future';
  }

  // Lunch Money budgets as plan targets (owner decision #821, 2026-11-18:
