        // by unconfirmedBills. Only an open period withholds it.
        remainingBills: planUnavailable || (!lookback && billLoadUnknown) ? null : remainingBills,
        ...(billLoadUnknownFrom ? { billLoadUnknownFrom } : {}),
        // Completed periods only, so every other period's publication is
        // unchanged: bills the evidence does not prove paid.
        ...(lookback ? historicalUnconfirmedBillsPublication(bills, scheduledBillAmountUnknown) : {}),
        periodBillLoad,
        periodBillLoadTrust,
        afterRemainingBills,
        afterBills,
        afterBillsTrust,
        householdBudget: planUnavailable ? [] : budget.items,
        // Savings audit (PR 1): display only. Already in observed Savings;
        // not in budgetHold, Balance After Deductions, the close or the sweep.
        ...(!planUnavailable && budget.savingsPaid ? { savingsPaidSpending: budget.savingsPaid } : {}),
        // Rank 18: the held rows and the one term BAD and the close deduct.
